	@Test
	void compiledProjectionAliasesRespectQueryPositionMasksAcrossAcceptedRows() {
		CountingSource source = new CountingSource();
		Value subjectValue = VF.createBNode("shared-result");
		Value objectValue = VF.createBNode("shared-result");
		source.put(42L, ValuePosition.SUBJECT, subjectValue);
		source.put(42L, ValuePosition.OBJECT, objectValue);
		NativeProjectedBindingSet.ProjectionLayout layout = NativeProjectedBindingSet.ProjectionLayout.create(
				new String[] { "subject", "subjectAlias", "object" }, new int[] { 0, 0, 1 },
				new int[] { ValuePosition.SUBJECT, ValuePosition.SUBJECT, ValuePosition.OBJECT });
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				assertThat(materializer.alias(0)).isZero();
				assertThat(materializer.alias(1)).isZero();
				assertThat(materializer.alias(2)).isEqualTo(2);
				assertThat(materializer.sameCacheBank(0, 1)).isTrue();
				assertThat(materializer.sameCacheBank(0, 2)).isFalse();

				NativeProjectedBindingSet first = capture(source, layout, new long[] { 42L, 42L }, materializer);
				NativeProjectedBindingSet second = capture(source, layout, new long[] { 42L, 42L }, materializer);

				assertThat(first.getValue("subjectAlias")).isSameAs(first.getValue("subject"));
				assertThat(first.getValue("object")).isSameAs(objectValue).isNotSameAs(subjectValue);
				assertThat(second.getValue("subject")).isSameAs(subjectValue);
				assertThat(second.getValue("object")).isSameAs(objectValue);
				assertThat(materializer.weakMisses()).isZero();
				assertThat(source.calls).containsExactly(
						new Lookup(42L, ValuePosition.SUBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
			}
			assertThat(ledger.usedBytes()).isZero();
		}
	}

	@Test
	void dynamicDuplicateTargetsKeepLastBoundOccurrenceAndLeaveUnboundTargetsAbsent() {
		CountingSource source = new CountingSource();
		Value firstX = VF.createBNode("first-x");
		Value other = VF.createBNode("other");
		Value lastX = VF.createBNode("last-x");
		source.put(42L, ValuePosition.SUBJECT | ValuePosition.OBJECT, firstX);
		source.put(43L, ValuePosition.SUBJECT, other);
		source.put(46L, ValuePosition.SUBJECT | ValuePosition.OBJECT, lastX);
		NativeProjectedBindingSet.ProjectionLayout layout = NativeProjectedBindingSet.ProjectionLayout.create(
				new String[] { "x", "other", "x" }, new int[] { 0, 1, 2 },
				new int[] { ValuePosition.SUBJECT, ValuePosition.SUBJECT, ValuePosition.OBJECT });
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet lastBound = capture(source, layout, new long[] { 42L, 43L, 46L },
						materializer);
				NativeProjectedBindingSet trailingUnbound = capture(source, layout,
						new long[] { 42L, 43L, NativeLmdbQuerySource.UNKNOWN_ID }, materializer);
				NativeProjectedBindingSet allUnbound = capture(source, layout,
						new long[] { NativeLmdbQuerySource.UNKNOWN_ID, 43L, NativeLmdbQuerySource.UNKNOWN_ID },
						materializer);
				NativeProjectedBindingSet afterUnbound = capture(source, layout,
						new long[] { 42L, 43L, 46L }, materializer);

				assertThat(lastBound.getBindingNames()).containsExactly("x", "other");
				assertThat(lastBound.getValue("x")).isSameAs(lastX);
				assertThat(trailingUnbound.getValue("x")).isSameAs(firstX);
				assertThat(allUnbound.hasBinding("x")).isFalse();
				assertThat(allUnbound.getValue("x")).isNull();
				assertThat(afterUnbound.getValue("x")).isSameAs(lastX);
				assertThat(source.calls).containsExactly(
						new Lookup(46L, ValuePosition.SUBJECT | ValuePosition.OBJECT),
						new Lookup(43L, ValuePosition.SUBJECT),
						new Lookup(42L, ValuePosition.SUBJECT | ValuePosition.OBJECT),
						new Lookup(46L, ValuePosition.SUBJECT | ValuePosition.OBJECT));
			}
		}
	}

	@Test
	void cacheStateIsPerEvaluationAndChangesWithTheResultValueScope() {
		CountingSource source = new CountingSource();
		Value firstValue = VF.createBNode("first-view");
		Value secondValue = VF.createBNode("second-view");
		source.put(42L, ValuePosition.OBJECT, firstValue);
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger firstLedger = manager.openQuery();
				LmdbQueryMemoryManager.QueryLedger secondLedger = manager.openQuery()) {
			NativeResultMaterializer firstEvaluation = plan.open(firstLedger);
			NativeResultMaterializer secondEvaluation = plan.open(secondLedger);
			assertThat(firstEvaluation).isNotNull();
			assertThat(secondEvaluation).isNotNull();
			try (firstEvaluation; secondEvaluation) {
				NativeProjectedBindingSet first = capture(source, layout, new long[] { 42L }, firstEvaluation);
				NativeProjectedBindingSet replay = capture(source, layout, new long[] { 42L }, firstEvaluation);
				NativeProjectedBindingSet independent = capture(source, layout, new long[] { 42L }, secondEvaluation);

				assertThat(first.getValue("value")).isSameAs(firstValue);
				assertThat(replay.getValue("value")).isSameAs(firstValue);
				assertThat(independent.getValue("value")).isSameAs(firstValue);
				assertThat(source.calls).hasSize(2);

				source.put(42L, ValuePosition.OBJECT, secondValue);
				source.advanceResultValueScope();
				NativeProjectedBindingSet changedView = capture(source, layout, new long[] { 42L }, firstEvaluation);
				NativeProjectedBindingSet changedViewReplay = capture(source, layout, new long[] { 42L },
						firstEvaluation);

				assertThat(changedView.getValue("value")).isSameAs(secondValue);
				assertThat(changedViewReplay.getValue("value")).isSameAs(secondValue);
				assertThat(source.calls).hasSize(3);
			}
		}
	}

