	@Test
	void clearedWeakReferentFallsBackAndIncrementsTheWeakMissCount(TestReporter reporter) {
		CountingSource source = new CountingSource();
		source.put(42L, ValuePosition.OBJECT, VF.createBNode("weak-cache-value"));
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				WeakReference<Value> cachedValue = captureWeakValue(source, layout, materializer);
				// A fresh wrapper with the same term keeps the source's semantic ID-to-value view stable.
				Value replacement = VF.createBNode("weak-cache-value");
				source.put(42L, ValuePosition.OBJECT, replacement);
				for (int attempt = 0; attempt < 5 && cachedValue.get() != null; attempt++) {
					System.gc();
				}
				boolean referentCollected = cachedValue.get() == null;
				reporter.publishEntry("weak-cache-referent-collected", Boolean.toString(referentCollected));
				System.out.println("weak-cache-referent-collected=" + referentCollected);
				assumeTrue(referentCollected,
						"conditional weak-cache miss was not observed because GC retained the original value");

				NativeProjectedBindingSet afterCollection = capture(source, layout, new long[] { 42L }, materializer);

				assertThat(afterCollection.getValue("value")).isSameAs(replacement);
				assertThat(source.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
				assertThat(materializer.weakMisses()).isEqualTo(1L);
			}
		}
	}

	@Test
	void wideProjectionRollsBackCacheHitsAndAliasesAcrossTheLongMaskBoundary() {
		int width = 70;
		String[] names = new String[width];
		int[] sourceSlots = new int[width];
		int[] positionMasks = new int[width];
		long[] rowIds = new long[width];
		LmdbLiteral[] oldValues = new LmdbLiteral[width];
		LmdbLiteral[] newValues = new LmdbLiteral[width];
		CountingSource source = new CountingSource();
		Set<Long> uniqueSourceIds = new HashSet<>();
		for (int i = 0; i < width; i++) {
			names[i] = "value" + i;
			sourceSlots[i] = i;
			positionMasks[i] = ValuePosition.OBJECT;
			rowIds[i] = 1_000L + i;
			oldValues[i] = i == width - 1
					? new ScopeChangingLiteral(new ValueStoreRevision.Default(null), "old-" + i, rowIds[i])
					: new LmdbLiteral(new ValueStoreRevision.Default(null), "old-" + i, rowIds[i]);
			newValues[i] = new LmdbLiteral(new ValueStoreRevision.Default(null), "new-" + i, rowIds[i]);
			source.put(rowIds[i], ValuePosition.OBJECT, oldValues[i]);
		}
		// Canonical target 64 aliases target 0, exercising a reusable mask word beyond bit 63.
		sourceSlots[64] = 0;
		for (int sourceSlot : sourceSlots) {
			uniqueSourceIds.add(rowIds[sourceSlot]);
		}
		NativeProjectedBindingSet.ProjectionLayout layout = NativeProjectedBindingSet.ProjectionLayout.create(
				names, sourceSlots, positionMasks);
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(50_000L, 50_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				assertThat(materializer.alias(0)).isZero();
				assertThat(materializer.alias(64)).isZero();
				assertThat(materializer.sameCacheBank(0, 64)).isTrue();
				assertThat(uniqueSourceIds).hasSize(69);

				NativeProjectedBindingSet first = capture(source, layout, rowIds, materializer);
				for (int i = 0; i < width; i++) {
					assertThat(first.getValue(names[i])).isSameAs(oldValues[sourceSlots[i]]);
				}
				assertThat(source.calls).hasSize(uniqueSourceIds.size());

				((ScopeChangingLiteral) oldValues[width - 1]).changeBeforeNextVersionCheck(() -> {
					for (int i = 0; i < width; i++) {
						source.put(rowIds[i], ValuePosition.OBJECT, newValues[i]);
					}
					source.advanceResultValueScope();
				});
				NativeProjectedBindingSet changedView = capture(source, layout, rowIds, materializer);

				for (int i = 0; i < width; i++) {
					assertThat(changedView.getValue(names[i])).isSameAs(newValues[sourceSlots[i]]);
				}
				assertThat(changedView.getValue(names[0])).isSameAs(changedView.getValue(names[64]));
				assertThat(source.calls).hasSize(uniqueSourceIds.size() * 2);
				for (long id : uniqueSourceIds) {
					long callsForIdAndMask = source.calls.stream()
							.filter(call -> call.id() == id && call.mask() == ValuePosition.OBJECT)
							.count();
					assertThat(callsForIdAndMask).isEqualTo(2L);
				}
			}
		}
	}

	@Test
	void nativeSemanticMutationInvalidatesTheCachedIdAndColumnValue() {
		CountingSource source = new CountingSource();
		LmdbLiteral mutable = new LmdbLiteral(new ValueStoreRevision.Default(null), "before", 42L);
		source.put(42L, ValuePosition.OBJECT, mutable);
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet before = capture(source, layout, new long[] { 42L }, materializer);
				NativeProjectedBindingSet unchanged = capture(source, layout, new long[] { 42L }, materializer);
				assertThat(before.getValue("value")).isSameAs(mutable);
				assertThat(unchanged.getValue("value")).isSameAs(mutable);
				assertThat(source.calls).hasSize(1);

				mutable.setLabel("after");
				NativeProjectedBindingSet changed = capture(source, layout, new long[] { 42L }, materializer);

				assertThat(changed.getValue("value")).isSameAs(mutable);
				assertThat(((Literal) changed.getValue("value")).getLabel()).isEqualTo("after");
				assertThat(source.calls).hasSize(2);
			}
		}
	}

	@Test
	void simpleIriNamespaceBoundaryMutationDeclinesTheOldStringWitness() {
		CountingSource source = new CountingSource();
		SimpleIRI oldValue = SimpleIRIExposureForTest.createWithSplit("urn:", "prefix:leaf");
		SimpleIRI freshValue = SimpleIRIExposureForTest.createWithSplit("urn:", "prefix:leaf");
		String originalString = oldValue.stringValue();
		source.put(42L, ValuePosition.OBJECT, oldValue);
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		assertThat(oldValue.getNamespace()).isEqualTo("urn:");
		assertThat(oldValue.getLocalName()).isEqualTo("prefix:leaf");
		assertThat(freshValue.getNamespace()).isEqualTo("urn:");
		assertThat(freshValue.getLocalName()).isEqualTo("prefix:leaf");
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet first = capture(source, layout, new long[] { 42L }, materializer);
				assertThat(first.getValue("value")).isSameAs(oldValue);

				SimpleIRIExposureForTest.resetSplitWithSameString(oldValue);
				assertThat(oldValue.stringValue()).isSameAs(originalString);
				assertThat(oldValue.getNamespace()).isEqualTo("urn:prefix:");
				assertThat(oldValue.getLocalName()).isEqualTo("leaf");
				source.put(42L, ValuePosition.OBJECT, freshValue);

				NativeProjectedBindingSet afterBoundaryChange = capture(source, layout, new long[] { 42L },
						materializer);

				assertThat(afterBoundaryChange.getValue("value")).isSameAs(freshValue);
				assertThat(source.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
			}
		}
	}

