		CountingSource source = new CountingSource();
		LmdbLiteral oldLeft = new LmdbLiteral(new ValueStoreRevision.Default(null), "old-left", 42L);
		ScopeChangingLiteral oldRight = new ScopeChangingLiteral(new ValueStoreRevision.Default(null), "old-right",
				43L);
		LmdbLiteral newLeft = new LmdbLiteral(new ValueStoreRevision.Default(null), "new-left", 42L);
		LmdbLiteral newRight = new LmdbLiteral(new ValueStoreRevision.Default(null), "new-right", 43L);
		source.put(42L, ValuePosition.OBJECT, oldLeft);
		source.put(43L, ValuePosition.OBJECT, oldRight);
		NativeProjectedBindingSet.ProjectionLayout layout = twoValueColumns();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet first = capture(source, layout, new long[] { 42L, 43L }, materializer);
				oldRight.changeBeforeNextVersionCheck(() -> {
					source.put(42L, ValuePosition.OBJECT, newLeft);
					source.put(43L, ValuePosition.OBJECT, newRight);
					source.advanceResultValueScope();
				});

				NativeProjectedBindingSet changedView = capture(source, layout, new long[] { 42L, 43L }, materializer);

				assertThat(first.getValue("left")).isSameAs(oldLeft);
				assertThat(first.getValue("right")).isSameAs(oldRight);
				assertThat(changedView.getValue("left")).isSameAs(newLeft);
				assertThat(changedView.getValue("right")).isSameAs(newRight);
				assertThat(source.calls).containsExactlyInAnyOrder(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(43L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(43L, ValuePosition.OBJECT));
			}
		}
