	@Test
	void retiringOneNamespacePreservesAnOverlappingLiveNamespace() {
		CountingSource source = new CountingSource();
		Value retiringValue = VF.createBNode("factor-namespace-retiring");
		Value liveValue = VF.createBNode("factor-namespace-live");
		source.put(42L, ValuePosition.OBJECT, retiringValue);
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		NamespaceCoordinates coordinates = new NamespaceCoordinates();
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet retiring = captureAtPosition(source, layout, materializer, coordinates, 42L,
						201L, 0L);
				materializer.unbound(0);
				source.put(42L, ValuePosition.OBJECT, liveValue);
				coordinates.changedSlots(1L);
				NativeProjectedBindingSet live = captureAtPosition(source, layout, materializer, coordinates, 42L, 202L,
						0L);
				long retainedBeforeRetirement = materializer.retainedBytes();
				assertThat(retainedBeforeRetirement).isPositive();

				coordinates.retire(201L);
				materializer.unbound(0);
				NativeProjectedBindingSet replayLive = captureAtPosition(source, layout, materializer, coordinates, 42L,
						202L, 0L);

				assertThat(retiring.getValue("value")).isSameAs(retiringValue);
				assertThat(replayLive.getValue("value")).isSameAs(liveValue);
				assertThat(coordinates.drainedNamespaces).containsExactly(201L);
				assertThat(materializer.retainedBytes())
						.as("retiring one generation removes its page while retaining the colliding live page")
						.isPositive()
						.isLessThan(retainedBeforeRetirement);
				assertThat(source.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
			}
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

