	@Test
	void acceptedReplayHitAdmitsItsOriginalFactorCoordinate() {
		CountingSource source = new CountingSource();
		Value repeated = VF.createBNode("accepted-factor-repeated");
		Value finalMember = VF.createBNode("accepted-factor-final");
		source.put(42L, ValuePosition.OBJECT, repeated);
		source.put(43L, ValuePosition.OBJECT, finalMember);
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(30_000L, 30_000L);
		ReplayCoordinates coordinates = new ReplayCoordinates();

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				List<NativeProjectedBindingSet> acceptedRows = new ArrayList<>();
				List<Value> retainedValues = new ArrayList<>();

				NativeProjectedBindingSet firstA = prepareAtPosition(source, layout, materializer, coordinates, 42L,
						0L);
				firstA.captureForOutput(null);
				acceptedRows.add(firstA);
				retainedValues.add(firstA.getValue("value"));

				NativeProjectedBindingSet secondA = prepareAtPosition(source, layout, materializer, coordinates, 42L,
						1L);
				secondA.captureForOutput(null);
				acceptedRows.add(secondA);
				retainedValues.add(secondA.getValue("value"));

				NativeProjectedBindingSet b = prepareAtPosition(source, layout, materializer, coordinates, 43L, 2L);
				b.captureForOutput(null);
				acceptedRows.add(b);
				retainedValues.add(b.getValue("value"));

				// The next outer member replays [A, A, B]. Its first A is rejected, but the second A is accepted.
				prepareAtPosition(source, layout, materializer, coordinates, 42L, 0L);
				NativeProjectedBindingSet replayedSecondA = prepareAtPosition(source, layout, materializer,
						coordinates, 42L, 1L);
				replayedSecondA.captureForOutput(null);
				acceptedRows.add(replayedSecondA);
				retainedValues.add(replayedSecondA.getValue("value"));

				assertThat(acceptedRows).hasSize(4);
				assertThat(retainedValues.get(0)).isSameAs(repeated);
				assertThat(retainedValues.get(0)).isSameAs(retainedValues.get(1));
				assertThat(retainedValues.get(0)).isSameAs(retainedValues.get(3));
				assertThat(retainedValues.get(2)).isSameAs(finalMember);
				assertThat(source.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(43L, ValuePosition.OBJECT));
			}
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@Test
	void tupleColumnsReuseAcrossOuterMembersAndDescriptorRebind() {
		CountingSource source = new CountingSource();
		Value leftFirst = VF.createBNode("tuple-left-201");
		Value rightFirst = VF.createBNode("tuple-right-301");
		Value leftSecond = VF.createBNode("tuple-left-202");
		Value rightSecond = VF.createBNode("tuple-right-302");
		source.put(201L, ValuePosition.OBJECT, leftFirst);
		source.put(301L, ValuePosition.OBJECT, rightFirst);
		source.put(202L, ValuePosition.OBJECT, leftSecond);
		source.put(302L, ValuePosition.OBJECT, rightSecond);
		NativeProjectedBindingSet.ProjectionLayout layout = NativeProjectedBindingSet.ProjectionLayout.create(
				new String[] { "left", "right" }, new int[] { 1, 2 },
				new int[] { ValuePosition.OBJECT, ValuePosition.OBJECT });
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(40_000L, 40_000L);
		long[][] tupleRows = { { 201L, 301L }, { 202L, 302L } };

		try (HeapFactorSource heap = new HeapFactorSource(this);
				TestTupleSource tupleSource = new TestTupleSource(tupleRows)) {
			BorrowedFactorBatch outer = new BorrowedFactorBatch(heap, 1);
			outer.reset(1);
			outer.bindHeap(0, new long[] { 901L, 902L }, 0, 2);
			BorrowedTupleBatch tuples = tupleSource.batch();
			FactorEnvironment environment = new FactorEnvironment(3);
			environment.bind(0, outer, 0, 0L);
			environment.bindTuple(new int[] { 1, 2 }, tuples, 0, 0L);
			try (FactorProductCursor product = new FactorProductCursor(3, 1);
					LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
				product.bind(environment, 7L, 1L);
				long initialActivation = 0L;
				NativeResultCoordinates coordinates = new NativeResultCoordinates() {
					@Override
					public long coordinateActivation() {
						return product.coordinateActivation();
					}

					@Override
					public boolean resultCoordinate(int slot, long[] coordinate) {
						return product.resultCoordinate(slot, coordinate);
					}
				};
				NativeResultMaterializer materializer = plan.open(ledger);
				assertThat(materializer).isNotNull();
				try (materializer) {
					List<NativeProjectedBindingSet> retained = new ArrayList<>();
					List<Long> memberPositions = new ArrayList<>();
					while (product.next()) {
						if (initialActivation == 0L) {
							initialActivation = product.coordinateActivation();
						}
						long[] leftCoordinate = new long[NativeResultCoordinates.WIDTH];
						long[] rightCoordinate = new long[NativeResultCoordinates.WIDTH];
						assertThat(product.resultCoordinate(1, leftCoordinate)).isTrue();
						assertThat(product.resultCoordinate(2, rightCoordinate)).isTrue();
						assertThat(leftCoordinate[NativeResultCoordinates.COLUMN]).isZero();
						assertThat(rightCoordinate[NativeResultCoordinates.COLUMN]).isEqualTo(1L);
						assertThat(rightCoordinate[NativeResultCoordinates.POSITION])
								.isEqualTo(leftCoordinate[NativeResultCoordinates.POSITION]);
						memberPositions.add(leftCoordinate[NativeResultCoordinates.POSITION]);
						long[] rowIds = { product.value(0), product.value(1), product.value(2) };
						retained.add(captureAtPosition(source, layout, materializer, coordinates, rowIds));
					}

					assertThat(memberPositions).containsExactly(0L, 1L, 0L, 1L);
					assertThat(source.calls).containsExactly(
							new Lookup(201L, ValuePosition.OBJECT),
							new Lookup(301L, ValuePosition.OBJECT),
							new Lookup(202L, ValuePosition.OBJECT),
							new Lookup(302L, ValuePosition.OBJECT));
					assertThat(retained.get(0).getValue("left")).isSameAs(retained.get(2).getValue("left"));
					assertThat(retained.get(0).getValue("right")).isSameAs(retained.get(2).getValue("right"));
					assertThat(retained.get(1).getValue("left")).isSameAs(retained.get(3).getValue("left"));
					assertThat(retained.get(1).getValue("right")).isSameAs(retained.get(3).getValue("right"));

					long generation = tuples.generation();
					tuples.bind(0, 0L, tupleRows.length);
					assertThat(tuples.generation()).isEqualTo(generation);
					Value reboundLeft = VF.createBNode("tuple-left-201");
					Value reboundRight = VF.createBNode("tuple-right-301");
					source.put(201L, ValuePosition.OBJECT, reboundLeft);
					source.put(301L, ValuePosition.OBJECT, reboundRight);
					product.bind(environment, 7L, 1L);
					assertThat(product.next()).isTrue();
					assertThat(product.coordinateActivation()).isGreaterThan(initialActivation);
					long[] reboundRow = { product.value(0), product.value(1), product.value(2) };
					NativeProjectedBindingSet afterRebind = captureAtPosition(source, layout, materializer,
							coordinates, reboundRow);

					assertThat(afterRebind.getValue("left")).isSameAs(reboundLeft);
					assertThat(afterRebind.getValue("right")).isSameAs(reboundRight);
					assertThat(afterRebind.getValue("left")).isNotSameAs(retained.get(0).getValue("left"));
					assertThat(afterRebind.getValue("right")).isNotSameAs(retained.get(0).getValue("right"));
					assertThat(source.calls).containsExactly(
							new Lookup(201L, ValuePosition.OBJECT),
							new Lookup(301L, ValuePosition.OBJECT),
							new Lookup(202L, ValuePosition.OBJECT),
							new Lookup(302L, ValuePosition.OBJECT),
							new Lookup(201L, ValuePosition.OBJECT),
							new Lookup(301L, ValuePosition.OBJECT));
				}
				assertThat(ledger.usedBytes()).isZero();
			}
			assertThat(manager.usedBytes()).isZero();
		}
	}

	@Test
	void unchangedMiddleFactorAvoidsPerInnerRowCoordinateScansAndKeepsSkippedChanges() {
		long[] outerIds = { 10L, 11L };
		long[] middleIds = { 20L, 21L };
		long[] innerIds = new long[12];
		for (int index = 0; index < innerIds.length; index++) {
			innerIds[index] = 30L + index;
		}
		CountingSource source = new CountingSource();
		Map<Long, Value> values = new HashMap<>();
		for (long id : outerIds) {
			values.put(id, VF.createBNode("outer-" + id));
		}
		for (long id : middleIds) {
			values.put(id, VF.createBNode("middle-" + id));
		}
		for (long id : innerIds) {
			values.put(id, VF.createBNode("inner-" + id));
		}
		values.forEach((id, value) -> source.put(id, ValuePosition.OBJECT, value));
		NativeProjectedBindingSet.ProjectionLayout layout = NativeProjectedBindingSet.ProjectionLayout.create(
				new String[] { "outer", "middle", "inner" }, new int[] { 0, 1, 2 },
				new int[] { ValuePosition.OBJECT, ValuePosition.OBJECT, ValuePosition.OBJECT });
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);

		try (HeapFactorSource heap = new HeapFactorSource(this);
				LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				FactorProductCursor product = new FactorProductCursor(3, 1)) {
			BorrowedFactorBatch outer = new BorrowedFactorBatch(heap, 1);
			outer.reset(1);
			outer.bindHeap(0, outerIds, 0, outerIds.length);
			BorrowedFactorBatch middle = new BorrowedFactorBatch(heap, 1);
			middle.reset(1);
			middle.bindHeap(0, middleIds, 0, middleIds.length);
			BorrowedFactorBatch inner = new BorrowedFactorBatch(heap, 1);
			inner.reset(1);
			inner.bindHeap(0, innerIds, 0, innerIds.length);
			FactorEnvironment environment = new FactorEnvironment(3);
			environment.bind(0, outer, 0, 0L);
			environment.bind(1, middle, 0, 0L);
			environment.bind(2, inner, 0, 0L);
			product.bind(environment, 7L, 1L);
			CountingFactorCoordinates coordinates = new CountingFactorCoordinates(product);
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				List<Value> retained = new ArrayList<>();
				while (product.next()) {
					long[] row = factorRow(product);
					retained.add(captureAtPosition(source, layout, materializer, coordinates, row).getValue("middle"));
				}
				long fullProductMiddleCalls = coordinates.resultCoordinateCalls[1];

				product.bind(environment, 7L, 1L);
				assertThat(product.next()).isTrue();
				long[] firstRow = factorRow(product);
				retained.add(captureAtPosition(source, layout, materializer, coordinates, firstRow).getValue("middle"));
				long middleCallsAfterFirstAcceptedRow = coordinates.resultCoordinateCalls[1];

				long[] lastInnerRow = firstRow;
				for (int index = 1; index < innerIds.length; index++) {
					assertThat(product.next()).isTrue();
					lastInnerRow = factorRow(product);
				}
				retained.add(
						captureAtPosition(source, layout, materializer, coordinates, lastInnerRow).getValue("middle"));
				long middleCallsAfterInnerRows = coordinates.resultCoordinateCalls[1];

				// Skip through a different middle member and back to its original member before accepting again.
				long[] returnedMiddleRow = lastInnerRow;
				for (int index = 0; index <= innerIds.length; index++) {
					assertThat(product.next()).isTrue();
					returnedMiddleRow = factorRow(product);
				}
				retained.add(captureAtPosition(source, layout, materializer, coordinates, returnedMiddleRow)
						.getValue("middle"));
				long middleCallsAfterSkippedReturn = coordinates.resultCoordinateCalls[1];

				assertThat(returnedMiddleRow[1]).isEqualTo(middleIds[0]);
				assertThat(retained).hasSize(outerIds.length * middleIds.length * innerIds.length + 3);
				assertThat(fullProductMiddleCalls).isEqualTo(outerIds.length * middleIds.length);
				assertThat(middleCallsAfterInnerRows).isEqualTo(middleCallsAfterFirstAcceptedRow);
				assertThat(middleCallsAfterSkippedReturn).isEqualTo(middleCallsAfterInnerRows + 1L);
			}
		}
	}

	@Test
	void factorPageWeakMissUsesTheCapturedMember(TestReporter reporter) {
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		CountingSource weakSource = new CountingSource();
		weakSource.put(42L, ValuePosition.OBJECT, VF.createBNode("factor-weak-member"));
		Value replacement = VF.createBNode("factor-weak-member");
		long firstPosition = 1L << 34;
		TestCoordinates weakCoordinates = new TestCoordinates(Map.of(42L, firstPosition, 43L, firstPosition + 1L));
		weakSource.put(43L, ValuePosition.OBJECT, VF.createBNode("factor-weak-intervening"));
		LmdbQueryMemoryManager weakManager = LmdbQueryMemoryManager.createForTesting(30_000L, 30_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = weakManager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				WeakReference<Value> cached = captureWeakAtPosition(weakSource, layout, materializer,
						weakCoordinates, 42L);
				weakSource.put(42L, ValuePosition.OBJECT, replacement);
				for (int attempt = 0; attempt < 5 && cached.get() != null; attempt++) {
					System.gc();
				}
				boolean referentCollected = cached.get() == null;
				reporter.publishEntry("factor-page-referent-collected", Boolean.toString(referentCollected));
				System.out.println("factor-page-referent-collected=" + referentCollected);
				assumeTrue(referentCollected,
						"conditional factor-page weak miss was not observed because GC retained the original value");

				captureAtPosition(weakSource, layout, materializer, weakCoordinates, 43L);
				NativeProjectedBindingSet afterCollection = captureAtPosition(weakSource, layout, materializer,
						weakCoordinates, 42L);

				assertThat(afterCollection.getValue("value")).isSameAs(replacement);
				assertThat(weakSource.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(43L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
				assertThat(materializer.weakMisses()).isEqualTo(1L);
			}
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(weakManager.usedBytes()).isZero();
	}

