	@Test
	void cacheAdmissionDoesNotReclaimSharedQueryMemory() {
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		Value baseValue = VF.createBNode("base-admission-fallback");
		CountingSource baseSource = new CountingSource();
		baseSource.put(42L, ValuePosition.OBJECT, baseValue);
		int[] baseReclamationCalls = new int[2];
		LmdbQueryMemoryManager baseManager = LmdbQueryMemoryManager.createForTesting(700L, 700L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = baseManager.openQuery()) {
			assertThat(ledger.reserve(64L, nonReclaiming(baseReclamationCalls))).isNotNull();
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet row = capture(baseSource, layout, new long[] { 42L }, materializer);
				assertThat(row.getValue("value")).isSameAs(baseValue);
				assertThat(baseSource.calls).containsExactly(new Lookup(42L, ValuePosition.OBJECT));
				assertThat(materializer.retainedBytes()).isZero();
			}
		}

		Value factorFirst = VF.createBNode("factor-admission-first");
		Value factorSecond = VF.createBNode("factor-admission-second");
		CountingSource factorSource = new CountingSource();
		factorSource.put(42L, ValuePosition.OBJECT, factorFirst);
		factorSource.put(43L, ValuePosition.OBJECT, factorSecond);
		int[] factorReclamationCalls = new int[2];
		TestCoordinates coordinates = new TestCoordinates(Map.of(42L, 0L, 43L, 1L));
		LmdbQueryMemoryManager factorManager = LmdbQueryMemoryManager.createForTesting(900L, 900L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = factorManager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet first = capture(factorSource, layout, new long[] { 42L }, materializer);
				assertThat(first.getValue("value")).isSameAs(factorFirst);
				assertThat(ledger.reserve(64L, nonReclaiming(factorReclamationCalls))).isNotNull();
				NativeProjectedBindingSet second = captureAtPosition(factorSource, layout, materializer,
						coordinates, 43L);
				NativeProjectedBindingSet replay = captureAtPosition(factorSource, layout, materializer,
						coordinates, 42L);

				assertThat(second.getValue("value")).isSameAs(factorSecond);
				assertThat(replay.getValue("value")).isSameAs(factorFirst);
				assertThat(factorSource.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(43L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
				assertThat(materializer.retainedBytes()).isEqualTo(672L);
			}
		}

		int[] normalReclamationCalls = new int[2];
		LmdbQueryMemoryManager controlManager = LmdbQueryMemoryManager.createForTesting(700L, 700L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = controlManager.openQuery()) {
			assertThat(ledger.reserve(64L, new LmdbQueryMemoryManager.Reclaimable() {
				@Override
				public boolean spill() {
					normalReclamationCalls[0]++;
					return true;
				}

				@Override
				public boolean shed() {
					normalReclamationCalls[1]++;
					return true;
				}
			})).isNotNull();
			assertThat(ledger.reserve(672L, null)).isNotNull();
		}

		assertThat(baseReclamationCalls).containsExactly(0, 0);
		assertThat(factorReclamationCalls).containsExactly(0, 0);
		assertThat(normalReclamationCalls).containsExactly(1, 0);
	}

