	@Test
	void nativeLiteralDatatypeMutationAvoidsDictionaryIdSpill() throws IOException {
		ValueStore valueStore = mock(ValueStore.class);
		ValueStoreRevision revision = new ValueStoreRevision.Default(valueStore);
		SimpleIRI datatype = SimpleIRIExposureForTest.createWithSplit("urn:", "before");
		LmdbLiteral literal = new LmdbLiteral(revision, "label", datatype, 42L);
		CountingSource source = new CountingSource();
		source.idSpace(valueStore);
		source.put(42L, ValuePosition.NONE, literal);
		source.put(42L, ValuePosition.OBJECT, literal);
		SimpleModelExposureForTest.setIriString(datatype, "urn:after");
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		NativeSpillValueCodec codec = new NativeSpillValueCodec(new NativeCancellationToken(), null, null, source);
		try (DataOutputStream output = new DataOutputStream(bytes)) {
			codec.write(output, literal);
		}

		assertThat(bytes.toByteArray()[0]).isNotEqualTo((byte) NativeSpillValueCodec.TAG_STORE_TERM);
		Value decoded;
		try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			decoded = codec.read(input);
		}
		assertThat(decoded).isInstanceOf(Literal.class);
		assertThat(((Literal) decoded).getDatatype().stringValue()).isEqualTo("urn:after");
		assertThat(source.calls).isEmpty();
		assertThat(literal.getInternalID()).isEqualTo(LmdbValue.UNKNOWN_ID);
	}

