	private static LmdbQueryMemoryManager.Reclaimable nonReclaiming(int[] calls) {
		return new LmdbQueryMemoryManager.Reclaimable() {
			@Override
			public boolean spill() {
				calls[0]++;
				return false;
			}

			@Override
			public boolean shed() {
				calls[1]++;
				return false;
			}
		};
	}

	private static LmdbTripleTerm tripleValue(ValueStoreRevision revision, SimpleBNode subject, Value object, long id) {
		return new LmdbTripleTerm(revision, subject, CoreDatatype.XSD.STRING.getIri(), object, id);
	}

	private static void assertNativeTripleObjectMutation(Value oldChild, Value freshChild, Runnable mutation,
			boolean nested) {
		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		Value oldObject = nested
				? SimpleModelExposureForTest.simpleTripleTerm(CoreDatatype.XSD.STRING.getIri(),
						CoreDatatype.XSD.STRING.getIri(), oldChild)
				: oldChild;
		Value freshObject = nested
				? SimpleModelExposureForTest.simpleTripleTerm(CoreDatatype.XSD.STRING.getIri(),
						CoreDatatype.XSD.STRING.getIri(), freshChild)
				: freshChild;
		LmdbTripleTerm oldValue = tripleValue(revision, SimpleModelExposureForTest.simpleBNode("subject"), oldObject,
				42L);
		LmdbTripleTerm freshValue = tripleValue(revision, SimpleModelExposureForTest.simpleBNode("subject"),
				freshObject, 42L);
		CountingSource source = new CountingSource();
		source.put(42L, ValuePosition.OBJECT, oldValue);
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);

		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			try (materializer) {
				NativeProjectedBindingSet first = capture(source, layout, new long[] { 42L }, materializer);
				assertThat(first.getValue("value")).isSameAs(oldValue);
				mutation.run();
				source.put(42L, ValuePosition.OBJECT, freshValue);
				NativeProjectedBindingSet afterMutation = capture(source, layout, new long[] { 42L }, materializer);

				assertThat(afterMutation.getValue("value")).isSameAs(freshValue);
				assertThat(oldValue.getInternalID()).isEqualTo(LmdbValue.UNKNOWN_ID);
				assertThat(source.calls).containsExactly(
						new Lookup(42L, ValuePosition.OBJECT),
						new Lookup(42L, ValuePosition.OBJECT));
			}
		}
	}

	@Test
	void refusedMaterializerClaimsFallBackWithoutChangingResultsOrRepeatingScopeChecks() {
		NativeProjectedBindingSet.ProjectionLayout layout = oneValueColumn();
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		Value fallbackValue = VF.createIRI("urn:" + "long-value-".repeat(32));
		CountingSource source = new CountingSource();
		source.put(42L, ValuePosition.OBJECT, fallbackValue);

		LmdbQueryMemoryManager noAdmissionManager = LmdbQueryMemoryManager.createForTesting(1L, 1L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = noAdmissionManager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			assertThat(ledger.usedBytes()).isZero();
			try (materializer) {
				NativeProjectedBindingSet first = capture(source, layout, new long[] { 42L }, materializer);
				source.retireResultValueScope();
				NativeProjectedBindingSet second = capture(source, layout, new long[] { 42L }, materializer);
				assertThat(first.getValue("value")).isSameAs(fallbackValue);
				assertThat(second.getValue("value")).isSameAs(fallbackValue);
				assertThat(source.calls).hasSize(2);
				assertThat(source.resultValueScopeCalls).isEqualTo(1);
				assertThat(materializer.retainedBytes()).isZero();
				assertThat(materializer.weakMisses()).isZero();
				assertThat(ledger.usedBytes()).isZero();
			}
		}

		CountingSource closedSource = new CountingSource();
		closedSource.put(42L, ValuePosition.OBJECT, fallbackValue);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(10_000L, 10_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			NativeResultMaterializer materializer = plan.open(ledger);
			assertThat(materializer).isNotNull();
			NativeProjectedBindingSet first = capture(closedSource, layout, new long[] { 42L }, materializer);
			long acceptedReservation = ledger.usedBytes();
			int scopeSamplesBeforeClose = closedSource.resultValueScopeCalls;
			assertThat(acceptedReservation).isPositive();
			materializer.close();
			closedSource.retireResultValueScope();
			NativeProjectedBindingSet afterClose = capture(closedSource, layout, new long[] { 42L }, materializer);
			assertThat(first.getValue("value")).isSameAs(fallbackValue);
			assertThat(afterClose.getValue("value")).isSameAs(fallbackValue);
			assertThat(closedSource.calls).hasSize(2);
			assertThat(closedSource.resultValueScopeCalls).isEqualTo(scopeSamplesBeforeClose);
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

	private static NativeProjectedBindingSet.ProjectionLayout oneValueColumn() {
		return NativeProjectedBindingSet.ProjectionLayout.create(new String[] { "value" }, new int[] { 0 },
				new int[] { ValuePosition.OBJECT });
	}

	private static NativeProjectedBindingSet.ProjectionLayout twoValueColumns() {
		return NativeProjectedBindingSet.ProjectionLayout.create(new String[] { "left", "right" },
				new int[] { 0, 1 }, new int[] { ValuePosition.OBJECT, ValuePosition.OBJECT });
	}

	private static NativeProjectedBindingSet capture(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, long[] slots,
			NativeResultMaterializer materializer) {
		NativeProjectedBindingSet row = new NativeProjectedBindingSet(source, layout, slots, materializer);
		row.captureForOutput(null);
		return row;
	}

	private static NativeProjectedBindingSet captureAtPosition(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			TestCoordinates coordinates, long id) {
		long[] rowIds = { id };
		coordinates.bind(rowIds);
		return captureAtPosition(source, layout, materializer, (NativeResultCoordinates) coordinates, rowIds);
	}

	private static NativeProjectedBindingSet captureAtPosition(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			NamespaceCoordinates coordinates, long id, long namespace, long position) {
		coordinates.bind(id, namespace, position);
		long[] rowIds = { id };
		return captureAtPosition(source, layout, materializer, (NativeResultCoordinates) coordinates, rowIds);
	}

	private static NativeProjectedBindingSet captureAtPosition(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			NativeResultCoordinates coordinates, long[] rowIds) {
		NativeProjectedBindingSet row = new NativeProjectedBindingSet(source, layout, rowIds, materializer);
		row.setCoordinateSequence(materializer.position(coordinates, rowIds));
		row.captureForOutput(null);
		return row;
	}

	private static long[] factorRow(FactorProductCursor product) {
		return new long[] { product.value(0), product.value(1), product.value(2) };
	}

	private static NativeProjectedBindingSet prepareAtPosition(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			ReplayCoordinates coordinates, long id, long position) {
		long[] rowIds = { id };
		coordinates.bind(rowIds, position);
		NativeProjectedBindingSet row = new NativeProjectedBindingSet(source, layout, rowIds, materializer);
		row.setCoordinateSequence(materializer.position(coordinates, rowIds));
		return row;
	}

	private static WeakReference<Value> captureWeakAtPosition(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			TestCoordinates coordinates, long id) {
		NativeProjectedBindingSet row = captureAtPosition(source, layout, materializer, coordinates, id);
		return new WeakReference<>(row.getValue("value"));
	}

	private static WeakReference<Value> captureWeakValue(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer) {
		NativeProjectedBindingSet row = capture(source, layout, new long[] { 42L }, materializer);
		return new WeakReference<>(row.getValue("value"));
	}

